use super::*;
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotPhase};
fn cohort()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🚦️cohort/🔣️.json")).unwrap()}
fn owned()->LasSnapshot{let input=cohort();let mut value=snapshot();value.schema=input["literalSchema"].as_str().unwrap().into();value.header.system_identifier=input["literalText"].as_str().unwrap().into();value.header.generating_software=input["literalText"].as_str().unwrap().into();value.vlrs[0].description=input["literalText"].as_str().unwrap().into();value.header.number_of_point_records=u32::MAX;value.header.creation_year=u16::MAX;let original=value.points.clone();value.points=input["word64"].as_array().unwrap().iter().enumerate().map(|(index,word)|{let mut point=original[index%original.len()].clone();point.x=f64::from_bits(u64::from_str_radix(word.as_str().unwrap(),16).unwrap());point.intensity=u16::MAX;point.scan_angle_rank=i8::MIN;point}).collect();value}
fn large()->LasSnapshot{let input=cohort();let mut value=owned();value.points=(0..usize::try_from(input["workItems"].as_u64().unwrap()).unwrap()).map(|index|value.points[index%value.points.len()].clone()).collect();value}
fn payload(snapshot:&LasSnapshot,encoding:SnapshotEncoding)->store::io_schema::IoPayload{match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<LasSnapshot as store::ArtifactPack>::encode_pack(snapshot)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<LasSnapshot as store::ArtifactDsl>::print_dsl(snapshot))}}
fn database(snapshot:&LasSnapshot)->store::sqlite_snapshot::SqliteDatabase{snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap()}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_las_cohort_actual_declaration_erased_full_words_and_literals(){
 semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("LAS complete owned snapshot").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let codec=store::document_codec(crate::STDIO_LAS_DOCUMENT_SCHEMA).await.unwrap().unwrap();let capability=codec.snapshot_sqlite.as_ref().expect("LAS actual declaration must publish paid semantic capability");assert_eq!(capability.snapshot_type,Some(std::any::TypeId::of::<LasSnapshot>()));let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.las".into(),standard:"1.0".into(),subset:"*".into()};let snapshot=owned();let expected=database(&snapshot);
 for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let file=(capability.import)(&codec.schema,&dialect,expected.clone(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap().value;assert_eq!((capability.export)(&codec.schema,&dialect,&file,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap().value,expected);let restored=LasSnapshot::decode_sqlite_snapshot_native(&file,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();assert_eq!(database(&restored),expected);}
}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_las_cohort_actual_typed_files_preserve_full_domain(){
 use semio_framework_os_kernel::io::io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot};semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("LAS typed files").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.las".into(),standard:"1.0".into(),subset:"*".into()};let snapshot=owned();let expected=database(&snapshot);let directory=std::env::var_os("SEMIO_TEST_ARTIFACT_DIR").or_else(||std::env::var_os("SEMIO_TEST_ARTIFACTS_DIR")).expect("owning test artifact directory");
 for(index,encoding)in [SnapshotEncoding::Binary,SnapshotEncoding::Text].into_iter().enumerate(){let mut phases=Vec::new();let bytes=io_export_sqlite_snapshot(&dialect,&snapshot,encoding,Default::default(),&mut |event|{phases.push(event.phase);true}).await.unwrap().value;let path=std::path::PathBuf::from(&directory).join(format!("las-complete-owned-{index}.sqlite"));std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(&path,&bytes).unwrap();let reopened=std::fs::read(&path).unwrap();assert_eq!(&reopened[..16],b"SQLite format 3\0");let independently_reopened=sqlite(&reopened,"");let restored=io_import_sqlite_snapshot::<LasSnapshot>(&dialect,&independently_reopened,Default::default(),&mut |event|{phases.push(event.phase);true}).await.unwrap().value;assert_eq!(database(&restored),expected);assert!(!phases.iter().any(|phase|matches!(phase,SqliteSnapshotPhase::EncodeNative|SqliteSnapshotPhase::DecodeNative)));}
}
#[test]
fn sqlite_snapshot_las_cohort_native_input_interior_and_ceilings(){
 let input=cohort();let snapshot=large();for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let file=payload(&snapshot,encoding);for(limits,kind)in[(SqliteDatabaseLimits{max_rows:1,..Default::default()},semio_framework_value::ValueRefusalKind::WorkLimit),(SqliteDatabaseLimits{max_allocation_bytes:usize::try_from(input["budgetRoles"]["nativeInput"]["ceiling"].as_u64().unwrap()).unwrap(),..Default::default()},semio_framework_value::ValueRefusalKind::OwnershipLimit)]{let error=LasSnapshot::decode_sqlite_snapshot_native(&file,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).err().expect("LAS native admission must preserve the authored caller role");assert_eq!(error.kind,kind);}let mut interior=false;let result=LasSnapshot::decode_sqlite_snapshot_native(&file,&mut SqliteSnapshotControl::new(&mut |event|{if event.phase==SqliteSnapshotPhase::DecodeNative&&event.completed>=usize::try_from(input["cancelAfter"].as_u64().unwrap()).unwrap()&&event.completed<event.total{interior=true;return false;}true},Default::default()));assert!(result.is_err());assert!(interior,"LAS actual native decoding requires bounded interior work");}
}
#[test]
fn sqlite_snapshot_las_cohort_native_output_interior_and_ceilings(){
 let input=cohort();let snapshot=large();for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{for limits in [SqliteDatabaseLimits{max_rows:1,..Default::default()},SqliteDatabaseLimits{max_value_bytes:1,..Default::default()}]{assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}let mut interior=false;let result=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |event|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>=usize::try_from(input["cancelAfter"].as_u64().unwrap()).unwrap()&&event.completed<event.total{interior=true;return false;}true},Default::default()));assert!(result.is_err());assert!(interior,"LAS actual native encoding requires bounded interior work");}
}
#[test]
fn sqlite_snapshot_las_cohort_long_unicode_owned_copies_are_interior_controlled(){
 let input=cohort();for field in 0..4{let mut snapshot=owned();let value="x".repeat(usize::try_from(input["copyBytes"].as_u64().unwrap()).unwrap());match field{0=>snapshot.schema=value,1=>snapshot.header.system_identifier=value,2=>snapshot.header.generating_software=value,_=>snapshot.vlrs[0].description=value}let expected=database(&snapshot);for phase in [SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot]{let mut interior=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.completed>=usize::try_from(input["copyCancelAfter"].as_u64().unwrap()).unwrap()&&event.completed<event.total{interior=true;return false;}true};let mut control=SqliteSnapshotControl::new(&mut callback,Default::default());let result=if phase==SqliteSnapshotPhase::ProjectSnapshot{snapshot.to_sqlite_database(&mut control).map(|_|())}else{LasSnapshot::from_sqlite_database(&expected,&mut control).map(|_|())};assert!(result.is_err());assert!(interior);}}
}
#[test]
fn sqlite_snapshot_las_cohort_native_late_malformed_and_foreign_identity_refuse(){
 let snapshot=owned();let bytes=<LasSnapshot as store::ArtifactPack>::encode_pack(&snapshot);let text=<LasSnapshot as store::ArtifactDsl>::print_dsl(&snapshot);let mut truncated=bytes.clone();truncated.pop();let wrong=text.replacen("stdio.las","stdio.png",1);let extra=format!("{text} unknown=17");for file in [store::io_schema::IoPayload::Binary(truncated),store::io_schema::IoPayload::Text(wrong),store::io_schema::IoPayload::Text(extra)]{assert!(LasSnapshot::decode_sqlite_snapshot_native(&file,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).is_err());}
}
